class RunTests {
  public void runTests() {
    Object[][] tests = {
        // Example from the book
        { new String[] {
            "RRRGRB",
            "BGRGRR",
            "RRRGRR",
            "RGRRRR",
            "GBGRGG"
        },
            new int[][] {
                { 2, 1, 1, 2, 1, 1 },
                { 1, 1, 1, 3, 1, 2 },
                { 2, 1, 1, 4, 1, 2 },
                { 1, 1, 1, 1, 1, 1 },
                { 1, 2, 1, 1, 3, 4 }
            }
        },
        // Single row
        { new String[] { "RGB" },
            new int[][] { { 1, 1, 2 } }
        },
        // Single column
        { new String[] { "R", "G", "B" },
            new int[][] { { 1 }, { 1 }, { 2 } }
        },
        // All colors adjacent
        { new String[] {
            "RGB",
            "BGR"
        },
            new int[][] {
                { 1, 1, 1 },
                { 1, 1, 1 }
            }
        }
    };

    RgbDistances solution = new RgbDistances();
    for (Object[] test : tests) {
      String[] screenArray = (String[]) test[0];
      List<String> screen = Arrays.stream(screenArray)
          .collect(Collectors.toList());
      int[][] want = (int[][]) test[1];
      int[][] got = solution.solve(screen);
      if (!Arrays.deepEquals(got, want)) {
        throw new RuntimeException(String.format(
            "\nsolve(%s): got: %s, want: %s\n",
            screen, Arrays.deepToString(got), Arrays.deepToString(want)));
      }
    }
  }
}

public class Solution {
  public static void main(String[] args) {
    new RunTests().runTests();
  }
}
